          id: "philo-marxism-1-w1",
          title: "小论文：把一句「马克思说」拆成五层",
          prompt: "写一篇 800 至 1000 字的论文，任选一句你在网上或教材里见过的以「马克思认为」开头的断言（例如「马克思认为物质决定意识」「马克思认为历史必然经过五个阶段」「马克思认为宗教是人民的鸦片」），完成四件事：① 给出这句话的确切出处，若找不到就明确写「我未能找到出处」；② 按本讲的五层划分判定它属于哪一层，并说明理由；③ 用三问程序（出处、层次、靶点）分析它最弱的前提是什么；④ 至少回应一个针对你结论的反驳。不得使用「大家都知道」「教科书上都这么写」这类论据。",
