          author: "毛泽东",
          work: "《实践论》（1937 年 7 月，延安；收入《毛泽东选集》第 1 卷，题下副标题「论认识和实践的关系——知和行的关系」）",
          passage: "（一）你要知道梨子的滋味，你就得变革梨子，亲口吃一吃。\n\n（二）感觉到了的东西，我们不能立刻理解它，只有理解了的东西才更深刻地感觉它。感觉只解决现象问题，理论才解决本质问题。\n\n（三）认识从实践始，经过实践得到了理论的认识，还须再回到实践去。\n\n（四）将丰富的感觉材料加以去粗取精、去伪存真、由此及彼、由表及里的改造制作工夫。\n\n（五）真理的标准只能是社会的实践。\n\n（六）实践、认识、再实践、再认识，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度。",
          note: "以上六句为《实践论》原文的直接引用（中文原典，不是翻译），括号内的序号与条目编排由本课所加，原文是连续行文，中间有大量论述被略去。原文见《毛泽东选集》第 1 卷。读的时候注意《实践论》的论战对象：它反对的是教条主义与经验主义这两种党内倾向，因此每一句都带着针对性，不是中立的教科书定义。",
