          kind: "position",
          front: "有根据的可断言性（warranted assertibility）是谁的主张？它想替换掉什么？",
          back: "杜威的主张，见《逻辑：探究的理论》（1938）。他想替换掉「真理」这个名词，把认识重新描述为解决问题的过程：说一个判断成立，意思是它经过了合格的探究。与实践检验论的差别在于，它不再承诺一个独立于探究的符合关系；与詹姆斯的差别在于，它不把「对我有用」当作标准。",
