          front: "汤普森（E.P. Thompson, 1924—1993）对阶级的形成说了什么？他因此被谁批评？",
          back: "他在《英国工人阶级的形成》（1963）与《理论的贫困》（1978）里主张：阶级不是结构自动产出的东西，而是人在共同经验中形成的，工人自己的文化、组织与选择不能省略。安德森在《英国马克思主义的内部争论》（1980）里批评他放弃了理论，同时承认他指出了结构主义的盲点。这场争论的现状是：双方都承认结构限制与能动性同时存在，分歧在限制有多紧。",
          where: "philo-marxism-3"
