          back: "宿命论说结果不依赖任何人的行动；历史必然性（在可辩护的读法里）说的是结构强制与趋势，它约束的是行动的代价与可能性，不取消行动。判据：如果所有人都不行动，结果会不会不同？若会，就不是宿命论。文本依据：马克思《路易·波拿巴的雾月十八日》（1852）开篇「人们自己创造自己的历史」，同时限定「并不是在他们自己选定的条件下创造」。",
