          hidden: true,
          form: "P1：∀s(¬充分发挥(生产力,s) → ¬灭亡(s))；P2：∀r(¬成熟(物质条件,r) → ¬出现(r))；P3：桎梏(生产关系, 生产力) → 革命时代；C：决定(矛盾运动, 更替)",
