            "用「归根到底是经济决定的」这句话回避所有具体机制问题：它可以是结论，但不能是解释本身。",
            "把历史反例写成「也有例外情况」一句话带过，不说明反例打在论证的哪一步。",
            "把个人能动性问题处理成情绪表态（「所以我仍然要努力」），而不给出可检验的判据。"
