          md: "这一块不需要你选边，需要你分清三组不同的争论。\n\n**争论一：平台上的劳动者算什么？** 外卖骑手、网约车司机、平台主播常常在合同上是「独立承包人」而不是雇员：没有固定工资、自己承担车辆与设备成本、可以「自由」决定接不接单。但他们的接单方式、路线、时限与评价由算法系统实时决定，退出成本很高。按生产关系定义的三项判据逐条检查——谁占有主要生产资料（平台占有的是数据与算法基础设施，劳动者占有的是电瓶车与手机）、谁决定劳动过程（算法）、谁承担风险（劳动者）——答案并不单一。这不是理论失效，而是理论遇到了需要认真处理的边界案例。相关研究包括布雷弗曼式的去技能化分析、赖特的矛盾阶级位置框架，以及关于「数字劳动」的一批文献。\n\n**争论二：身份政治与阶级政治是否互斥？** 弗雷泽（Nancy Fraser）主张用「承认与再分配」的双维框架：身份承认的诉求与资源再分配的诉求都不是另一方的附带现象。**交叉性（intersectionality，克伦肖 Kimberlé Crenshaw 1989 年提出）**进一步主张：一个人同时处在多重社会位置中，这些位置造成的处境不能被化约为单一维度（例如一位黑人女性工人面对的处境，不等于「黑人问题」加「女性问题」加「工人问题」）。马克思主义一方最强的回应不是「身份政治不重要」，而是：**若不改变生产关系，承认的获得容易被收回**——法律上的平等可以在经济压力下变成空文。身份政治一方最强的回应同样具体：**阶级政治在历史上常常把女性、少数族裔与殖民地人民的问题推到「以后」**，而这个「以后」一再被推迟。把任何一方写成愚蠢，都是拒绝面对史料。\n\n**争论三：文化政治与经济焦虑的解释权。** 2016 年以后出现了大量关于「选举结果到底由经济焦虑还是文化认同驱动」的研究与争论。争论的方法论要点是：经济变量与文化变量高度相关，把它们当作互相排斥的解释，本身就是一种建模错误；真正可检验的提问方式是「在控制另一个变量后，哪一个的效应仍然显著」。\n\n**这一块的小结（本课的判断，不是引文）：** 阶级分析在平台经济与身份政治语境下的处境，不是被推翻，而是从「一套现成的答案」变成了「一套必须重新做经验工作的框架」。凡是宣称它已经过时或仍然够用的人，都需要交出经验研究，而不是立场表态。"
