          sample: "（以下为范例片段，不是标准答案。）「统治阶级的思想在每一时代都是占统治地位的思想」这句话要想被检验，先得被拆开。原文直接给出的是两条：统治阶级支配物质生产资料；支配物质生产资料的阶级同时也支配精神生产资料。但从第二条到结论之间还缺两步：支配传播工具是否等于决定传播内容，以及被系统传播的观念是否就是占统治地位的观念。本文要检验的正是这两步，尤其是第二步所带来的循环风险——如果「占统治地位」的判据就是「被广泛接受」，那么这句话就没有告诉我们任何新东西。",
