              note: "第三重规定。「类本质」（Gattungswesen）是费尔巴哈式的术语：人作为类，其特性是自由自觉的活动。这一步把劳动从「成为人的方式」降为「活着的手段」。这个术语在马克思后来的著作中基本消失，因此这一重规定也是「早期人本学框架是否被放弃」这场争论的焦点文本。"
